#include <bits/stdc++.h>
#define FORI(i,a,b) for(int i=(a);i<=(b);i++)
#define FORD(i,a,b) for(int i=(a);i>=(b);i--)
using namespace std;
const int MAX=505;
int n,m,mod;
int mod_value(int x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void add_mod(int &x,int y){
	x=mod_value(x+y);
}
int bin_pow(int base,int exp){
	int res=1;
	while(exp){
		if(exp&1)res=1ll*res*base%mod;
		base=1ll*base*base%mod;
		exp>>=1;
	}
	return res;
}
int fact[MAX*4],inv_fact[MAX*4];
void precompute(int n){
	fact[0]=1;
	FORI(i,1,n)fact[i]=1ll*fact[i-1]*i%mod;
	inv_fact[n]=bin_pow(fact[n],mod-2);
	FORD(i,n-1,0)inv_fact[i]=1ll*inv_fact[i+1]*(i+1)%mod;
}
int choose(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*fact[n]*inv_fact[n-m]%mod*inv_fact[m]%mod;
}
vector<int> polyF,gPoly;
int sumSeries(int x){
	return x*(x+1)/2;
}
vector<int> multiplyPoly(const vector<int> &A,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	FORI(i,0,(int)A.size()-1)FORI(j,0,(int)B.size()-1)add_mod(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int G(int n,int m){
	return choose(m+n-1,n-1);
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	precompute(m<<1);
	polyF.resize(n+1);gPoly.resize(n+1);
	polyF[0]=1;
	FORI(i,1,n){
		FORI(j,0,i-1)add_mod(polyF[i],1ll*polyF[j]*polyF[i-1-j]%mod*choose(i-1,j)%mod);
		polyF[i]=1ll*polyF[i]*(i+1)%mod;
	}
	FORI(i,1,n){
		FORI(j,0,i-1)add_mod(gPoly[i],(2ll*polyF[j]*gPoly[i-1-j]%mod*choose(i-1,j)%mod*(i+1)%mod+1ll*choose(i-1,j)*(sumSeries(j)+sumSeries(i-1-j))%mod*polyF[j]%mod*polyF[i-1-j]%mod)%mod);
	}
	polyF[0]=0;
	FORI(i,0,n)gPoly[i]=1ll*gPoly[i]*inv_fact[i]%mod;
	FORI(i,0,n)polyF[i]=1ll*polyF[i]*inv_fact[i]%mod;
	int total=0;
	FORI(i,1,m-n+1){
		add_mod(total,1ll*gPoly[n]*G(i+1,m-n-i+1)%mod*fact[n]%mod*i%mod);
		gPoly=multiplyPoly(gPoly,polyF);gPoly.resize(n+1);
	}
	cout<<total;
	return 0;
}
